"""BreastCare Agent installer. Run from project root; see AGENT_README.md after installation."""
import base64, json, zlib, sys, uuid, shutil
from pathlib import Path

PAYLOAD = ''

def main():
    root = Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve()
    if not root.is_dir():
        raise ValueError('Project directory does not exist')
    work = root/('.breastcare_agent_setup_'+uuid.uuid4().hex)
    work.mkdir()
    try:
        files = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
        for name,data in files.items():
            target = (work/name).resolve()
            if not target.is_relative_to(work.resolve()):
                raise ValueError('Invalid installer path')
            target.parent.mkdir(parents=True,exist_ok=True)
            target.write_bytes(base64.b64decode(data))
        namespace = {'__name__':'installer_module'}
        exec(compile((work/'install_agent.py').read_text(encoding='utf-8'),str(work/'install_agent.py'),'exec'),namespace)
        namespace['install'](root,work)
    finally:
        resolved = work.resolve()
        if resolved.parent == root and resolved.name.startswith('.breastcare_agent_setup_'):
            shutil.rmtree(resolved)

if __name__=='__main__':
    try:
        main()
    except Exception as e:
        print('ERROR:',e,file=sys.stderr)
        sys.exit(1)
